<!DOCTYPE html><html><head><title>Rooms</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StayEase Hotels</h1><nav><a href="index.php">Home</a><a href="rooms.php">Rooms</a><a href="dashboard.php">Dashboard</a><a href="my_bookings.php">My Bookings</a></nav></header><div class="container"><h2>Available Room Types</h2><div class="grid"><?php while($r=mysqli_fetch_assoc($rooms)){ ?><div class="room"><h3><?php echo htmlspecialchars($r['room_type']); ?></h3><p><?php echo htmlspecialchars($r['description']); ?></p><p>Rooms in inventory: <?php echo (int)$r['quantity']; ?></p><h3>₹<?php echo number_format($r['price'],2); ?> / night</h3><a class="btn" href="book.php?room_id=<?php echo $r['id']; ?>">Book this room</a></div><?php } ?></div></div><footer>Room prices may be updated by the administrator.</footer></body></html>